mapper.select:
select * from ( select SEM.emp_name ,SEM.user_type ,SEM.org_code ,SEM.org_name ,SEM.org_code_path ,SEM.org_name_path , sop.emp_no,sepc1.VEHICLE_INFO car_infos,sepc2.LOCK_VEHICLE lock_cars,sop.factory factory_code,sop.update_time ,'' REMARK from safety.safety_outsider_promise sop left join safety.safety_employee_message sem on sem.emp_no = sop.emp_no left join (select employee_no,group_concat(sepc.car_no) VEHICLE_INFO from safety.safety_employee_private_car sepc group by employee_no) sepc1 on sop.emp_no = sepc1.employee_no left join (select employee_no,group_concat(car_no) LOCK_VEHICLE from safety.safety_employee_private_car where lock_flag='是' group by employee_no) sepc2 on sop.emp_no = sepc1.employee_no where sop.factory not in ('','99') and sem.status = 'NORMAL'
union all select SEM.emp_name ,SEM.user_type ,SEM.org_code ,SEM.org_name ,SEM.org_code_path ,SEM.org_name_path , sop.emp_no,sepc1.VEHICLE_INFO car_infos,sepc2.LOCK_VEHICLE lock_cars,sop.factory factory_code,sop.update_time ,sop.REMARK from (select EMPLOYEE_CODE emp_no,group_concat(FACTORY_ID) factory,max(update_time) update_time,group_concat(DISTINCT remark) REMARK from safety_park_employee_power_info spepi where IS_DELETE = 0 group by EMPLOYEE_CODE ) sop left join safety.safety_employee_message sem on sem.emp_no = sop.emp_no left join (select employee_no,group_concat(sepc.car_no) VEHICLE_INFO from safety.safety_employee_private_car sepc group by employee_no) sepc1 on sop.emp_no = sepc1.employee_no left join (select employee_no,group_concat(car_no) LOCK_VEHICLE from safety.safety_employee_private_car where lock_flag='是' group by employee_no) sepc2 on sop.emp_no = sepc1.employee_no where 1 = 1 and sem.status = 'NORMAL'
) CUR_TABLE where 1= 1
order by ${orderByClause}
limit ${offset}, ${limit}
limit ${limit}

select count(1) from ( select SEM.emp_name ,SEM.user_type ,SEM.org_code ,SEM.org_name ,SEM.org_code_path ,SEM.org_name_path , sop.emp_no,sepc1.VEHICLE_INFO car_infos,sepc2.LOCK_VEHICLE lock_cars,sop.factory factory_code,sop.update_time , '' REMARK from safety.safety_outsider_promise sop left join safety.safety_employee_message sem on sem.emp_no = sop.emp_no left join (select employee_no,group_concat(sepc.car_no) VEHICLE_INFO from safety.safety_employee_private_car sepc group by employee_no) sepc1 on sop.emp_no = sepc1.employee_no left join (select employee_no,group_concat(car_no) LOCK_VEHICLE from safety.safety_employee_private_car where lock_flag='是' group by employee_no) sepc2 on sop.emp_no = sepc1.employee_no where sop.factory not in ('','99') and sem.status = 'NORMAL'
union all select SEM.emp_name ,SEM.user_type ,SEM.org_code ,SEM.org_name ,SEM.org_code_path ,SEM.org_name_path , sop.emp_no,sepc1.VEHICLE_INFO car_infos,sepc2.LOCK_VEHICLE lock_cars,sop.factory factory_code,sop.update_time , sop.REMARK from (select EMPLOYEE_CODE emp_no,group_concat(FACTORY_ID) factory,max(update_time) update_time,group_concat(remark) REMARK from safety_park_employee_power_info spepi where IS_DELETE = 0 group by EMPLOYEE_CODE ) sop left join safety.safety_employee_message sem on sem.emp_no = sop.emp_no left join (select employee_no,group_concat(sepc.car_no) VEHICLE_INFO from safety.safety_employee_private_car sepc group by employee_no) sepc1 on sop.emp_no = sepc1.employee_no left join (select employee_no,group_concat(car_no) LOCK_VEHICLE from safety.safety_employee_private_car where lock_flag='是' group by employee_no) sepc2 on sop.emp_no = sepc1.employee_no where 1 = 1 and sem.status = 'NORMAL'
) CUR_TABLE

select sop.*, sem.emp_name, sem.user_type, sem.org_code, sem.org_name, sem.org_code_path, sem.org_name_path from ( select emp_no empNo, factory factoryCode, update_time updateTime, remark from safety.safety_outsider_promise where factory not in ('', '99')
union all select EMPLOYEE_CODE empNo, group_concat(FACTORY_ID) factoryCode, max(update_time) updateTime, group_concat(DISTINCT remark) remark from safety_park_employee_power_info where IS_DELETE = 0
group by EMPLOYEE_CODE
having FIND_IN_SET(#{factoryCode},group_concat(FACTORY_ID))
) sop left join safety.safety_employee_message sem on sem.emp_no = sop.empNo where sem.status = 'NORMAL'
order by ${orderByClause}
limit ${offset}, ${limit}
limit ${limit}
